package com.autoops.execution.controller;import com.autoops.execution.realtime.ExecutionEventPublisher;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;@RestController public class ExecutionEventsController{private final ExecutionEventPublisher events;public ExecutionEventsController(ExecutionEventPublisher e){events=e;}@GetMapping("/api/executions/{id}/events")public SseEmitter events(@PathVariable Long id){return events.subscribe(id);}}
